using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public sealed class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker();

    #region GetStockLevel

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        var level = _tracker.GetStockLevel("UNKNOWN-001");

        Assert.AreEqual(0, level);
    }

    [TestMethod]
    public void GetStockLevel_AfterAddStock_ReturnsCorrectQuantity()
    {
        _tracker.AddStock("SKU-100", 25);

        Assert.AreEqual(25, _tracker.GetStockLevel("SKU-100"));
    }

    [TestMethod]
    public void GetStockLevel_NullSku_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _tracker.GetStockLevel(null!));
    }

    [TestMethod]
    public void GetStockLevel_EmptySku_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _tracker.GetStockLevel(""));
    }

    #endregion

    #region AddStock

    [TestMethod]
    [DataRow(1)]
    [DataRow(50)]
    [DataRow(1000)]
    public void AddStock_ValidQuantity_IncreasesLevel(int quantity)
    {
        _tracker.AddStock("SKU-A", quantity);

        Assert.AreEqual(quantity, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void AddStock_MultipleCalls_Accumulates()
    {
        _tracker.AddStock("SKU-A", 10);
        _tracker.AddStock("SKU-A", 5);

        Assert.AreEqual(15, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void AddStock_ZeroQuantity_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _tracker.AddStock("SKU-A", 0));
    }

    [TestMethod]
    public void AddStock_NegativeQuantity_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _tracker.AddStock("SKU-A", -5));
    }

    [TestMethod]
    public void AddStock_NullSku_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _tracker.AddStock(null!, 10));
    }

    #endregion

    #region RemoveStock

    [TestMethod]
    public void RemoveStock_ValidQuantity_DecreasesLevel()
    {
        _tracker.AddStock("SKU-B", 20);

        _tracker.RemoveStock("SKU-B", 8);

        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-B"));
    }

    [TestMethod]
    public void RemoveStock_EntireStock_LeavesZero()
    {
        _tracker.AddStock("SKU-B", 10);

